with RecentAccounts as (select * from accounts where customer_id is not null and account_type in ('CHECKING', 'CREDIT')), customer_id_summary as (select customer_id, count(case when account_type = 'CHECKING' then 1 end) as checking_count from RecentAccounts group by customer_id) select customer_id, checking_count from customer_id_summary where checking_count > 6 order by checking_count desc, customer_id limit 10;
